import java.io.*;
import java.util.*;

public class Main {
    static final InputStream is = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int rb() throws IOException {
        if (ptr == len) {
            len = is.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = rb();
        while (c != '-' && (c < '0' || c > '9')) c = rb();
        boolean neg = c == '-';
        if (neg) c = rb();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = rb();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }


    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt();
        long[] prefix = new long[n];
        long total = 0;
        for (int i = 0; i < n; i++) {
            total += nextLong();
            prefix[i] = total; // completion time of task i
        }
        long elapsed = 0;
        StringBuilder sb = new StringBuilder();
        for (int k = 0; k < m; k++) {
            elapsed += nextLong();
            int left;
            if (elapsed >= total) {
                left = 0;
                elapsed = 0; // excess discarded, next shift restarts the batch
            } else {
                int lo = 0, hi = n; // first prefix greater than elapsed
                while (lo < hi) {
                    int mid = (lo + hi) >>> 1;
                    if (prefix[mid] <= elapsed) lo = mid + 1;
                    else hi = mid;
                }
                left = n - lo;
            }
            sb.append(left).append(k + 1 < m ? ' ' : '\n');
        }
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"sort"
	"strconv"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	c, _ := reader.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = reader.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = reader.ReadByte()
	}
	n := 0
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = reader.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}


func main() {
	n, m := readInt(), readInt()
	prefix := make([]int, n)
	total := 0
	for i := range prefix {
		total += readInt()
		prefix[i] = total // completion time of task i
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	elapsed := 0
	for k := 0; k < m; k++ {
		elapsed += readInt()
		left := 0
		if elapsed >= total {
			elapsed = 0 // excess discarded, next shift restarts the batch
		} else {
			done := sort.Search(n, func(i int) bool { return prefix[i] > elapsed })
			left = n - done
		}
		w.WriteString(strconv.Itoa(left))
		if k+1 < m {
			w.WriteByte(' ')
		} else {
			w.WriteByte('\n')
		}
	}
}
